/** Typed access to the pinned NIST pulses.
 *
 * TWO sets, both pinned, both dated, neither regenerated by any script:
 *
 *   NIST          src/fixtures/nist.json          captured 2026-10-01
 *   NIST_CURRENT  src/fixtures/nist-current.json  captured 2026-11-10
 *
 * The historical set is kept deliberately. Between those two dates NIST's
 * signing certificate went from a 2048-bit key to a 4096-bit one, and the
 * 2026-10-01 pulses are the evidence for what that mismatch looked like: a
 * 4096-bit signature naming a certificate whose key could not have produced
 * it. Deleting them would leave the page asserting a fixed beacon with nothing
 * to show for the period when it was not.
 */
import raw from '../fixtures/nist.json'
import rawCurrent from '../fixtures/nist-current.json'
import type { Pulse } from './types'

interface NistFixtures {
  fetchedAt: string
  certificates: Record<string, string>
  recent: Pulse[]
  preRotation: Pulse[]
  rotation: Pulse
  skiplist: { target: number; anchor: number; pulses: Pulse[] }
}

/** The current set carries only what it needs to show the repaired state. */
interface NistCurrentFixtures {
  fetchedAt: string
  certificates: Record<string, string>
  recent: Pulse[]
}

export const NIST = raw as unknown as NistFixtures
export const NIST_CURRENT = rawCurrent as unknown as NistCurrentFixtures

export function certFor(p: Pulse): string | undefined {
  return NIST.certificates[p.certificateId.toLowerCase()]
}

/** The certificate a current-set pulse names, from the current set. */
export function certForCurrent(p: Pulse): string | undefined {
  return NIST_CURRENT.certificates[p.certificateId.toLowerCase()]
}

/** The date each set was captured, for any text that states one. */
export const CAPTURED = {
  historical: NIST.fetchedAt.slice(0, 10),
  current: NIST_CURRENT.fetchedAt.slice(0, 10),
} as const
